import { prepareRoutingRequest } from '../src/harness.js';
import { parseDecision, EFFORTS, belowApplyProbability } from '../src/policy.js';
import { parseHelperResult, validJevKey, PROCESS_ENV, PROCESS_TIMEOUT_MS } from '../src/providers/jev.js';
import { fakeProvider } from '../src/providers/fake.js';
import { summary, status, sessionNotice } from '../src/report.js';
import { usageRecord } from '../src/usage.js';

// Jev p90 reached ~630ms with timeouts at the old 1000ms wait (2026-10-05).
export const CLASSIFY_WAIT_MS = 1500;
// Jev taskContext budget (src/harness.js rejects more than 2000 characters).
const CONTEXT_PROMPT_CHARS = 600;
const CONTEXT_TOTAL_CHARS = 2000;

export function register(on, options) {
  registerRouter(on, fakeProvider(options.fakeChoice), options);
}

// The injected fake provider keeps lifecycle tests offline.
export function registerRouter(on, classify, options = {}) {
  const provider = options.provider === 'jev' ? 'jev' : 'fake';
  // A random share of applicable enforce turns stays unchanged as the
  // measurement control group; the injected random keeps tests deterministic.
  const holdoutRate = holdoutShare(options.holdoutRate);
  const random = typeof options.random === 'function' ? options.random : Math.random;
  const flight = { busy: false };
  let mode = 'off';
  let locked = false;
  let pending;
  // A user submission that was queued and has not started its turn yet.
  let queuedUser = false;
  let lastSummary;
  let project = null;
  const turns = new Map();
  const submissions = new Set();
  // Subagent turn id -> binding to the main turn running at its first step: the
  // inherited effort (undefined when it passes through unchanged) and a copy of
  // that main turn's decision for the usage log (none without a main turn).
  const subagents = new Map();
  // The last answered main turn, kept only with sendTaskContext: a prompt-only
  // request lacks what a short follow-up such as "fix it" refers to.
  const sendContext = provider === 'jev' && options.sendTaskContext === true;
  let previous;

  // shadow and enforce share classification; only enforce rewrites effort.
  function routing() {
    return (mode === 'shadow' || mode === 'enforce') && !locked;
  }

  function isActiveTurn(turnId, turn) {
    return turn.valid && turns.get(turnId) === turn && routing();
  }

  function invalidate() {
    pending = undefined;
    previous = undefined;
    queuedUser = false;
    for (const turn of turns.values()) invalidateTurn(turn);
    turns.clear();
    subagents.clear();
  }

  on('session.start', async ($, e, next) => {
    invalidate();
    mode = startMode(options);
    locked = false;
    lastSummary = undefined;
    project = typeof e.cwd === 'string' ? e.cwd : null;
    await $.command.register({ name: 'jet-router', description: 'Effort routing: observe (shadow) or apply per turn (enforce)',
      argumentHint: 'status|shadow|enforce|off|lock|unlock|report', immediate: true });
    publish($, sessionNotice(mode, provider));
    return next(e);
  });

  on('command.run', { command: 'jet-router' }, ($, e) => {
    const action = e.args.trim() || 'status';
    // Only report is asynchronous; the other commands answer synchronously.
    if (action === 'report' || action.startsWith('report ')) return runReport($, action.split(/\s+/).slice(1)).then(text => ({ text }));
    if (action === 'off' || action === 'shadow' || action === 'enforce') {
      invalidate();
      mode = action;
    } else if (action === 'lock' || action === 'unlock') {
      invalidate();
      locked = action === 'lock';
    } else if (action !== 'status') {
      return { text: `사용법: /jet-router status|shadow|enforce|off|lock|unlock\n${REPORT_USAGE}` };
    }
    try { $.ui.status(undefined); } catch { /* No interactive surface. */ }
    return { text: status(mode, locked, lastSummary, provider, options.cloudConsent === true, sendContext) };
  });

  on('prompt.submit', async ($, e, next) => {
    const user = ['composer', 'bridge'].includes(e.origin?.kind);
    const reason = skipReason(e, user);
    const ambiguous = mode === 'off' || locked || reason !== undefined;
    if (ambiguous) {
      for (const turn of turns.values()) invalidateTurn(turn);
    }
    const ticket = { text: ambiguous ? undefined : e.text, ambiguous, user, reason,
      command: e.text.trimStart().startsWith('/') };
    submissions.add(ticket);
    pending = ticket;
    try {
      return await next(e);
    } finally {
      // A turn must have consumed this exact submission synchronously through
      // next. Queued/blocked submissions cannot become a later turn's decision.
      if (pending === ticket) {
        pending = undefined;
        if (user) queuedUser = true;
      }
      submissions.delete(ticket);
    }
  });

  // Why a submission cannot be classified; undefined when it can.
  function skipReason(e, user) {
    if (submissions.size > 0 || turns.size > 0 || e.turnId !== undefined || e.wait) return 'overlap';
    if (!user) return 'origin';
    if (e.attachments?.length) return 'attachment';
    if (e.context?.length) return 'hidden-context';
    if (!e.text.trim()) return 'empty';
    if (e.text.length > 6000) return 'too-long';
    return undefined;
  }

  on('turn.start', ($, e, next) => {
    const ticket = pending;
    pending = undefined;
    const valid = routing() && turns.size === 0 &&
      ticket && !ticket.ambiguous && ticket.text === e.text;
    // Turns opened by subagent reports or task notifications stay tracked for
    // overlap checks but never produce a summary: nobody typed them.
    const silent = ticket ? !ticket.user : !queuedUser;
    // Skills and commands expand the typed text before the turn starts.
    let reason = 'queued';
    if (ticket) reason = ticket.reason ?? (ticket.ambiguous ? 'correlation'
      : turns.size > 0 ? 'overlap' : ticket.command ? 'command' : 'rewritten');
    queuedUser = false;
    for (const turn of turns.values()) invalidateTurn(turn);
    turns.clear();
    if (routing()) {
      turns.set(e.turnId, { valid: Boolean(valid), silent, reason, text: valid ? e.text : '', started: false,
        prompt: sendContext && valid ? e.text : null });
    }
    return next(e);
  });

  on('turn.complete', async ($, e, next) => {
    if (e.agentId !== undefined) {
      const bound = subagents.get(e.turnId);
      subagents.delete(e.turnId);
      const result = await next(e);
      if (routing() && bound?.record && options.usageLog === true) {
        await recordUsage($, usageRecord({ project, model: baseModel(bound.stepModel), kind: 'subagent', record: bound.record,
          outcome: e.reason, durationMs: e.durationMs, usage: e.usage }));
      }
      return result;
    }
    const turn = turns.get(e.turnId);
    if (!turn || turn.completing) return next(e);
    turn.completing = true;
    turn.valid = false;
    turn.cancel?.();
    try {
      const result = await next(e);
      // A notification turn the user did not type breaks the chain: sending the
      // turn before it would label stale text as the previous turn.
      if (sendContext && turns.get(e.turnId) === turn) {
        previous = routing() && !turn.silent && e.reason === 'answer' ? { prompt: turn.prompt, answer: e.answer } : undefined;
      }
      if (routing() && turns.get(e.turnId) === turn && turn.record) {
        lastSummary = summary(turn.record, e.reason);
        publish($, lastSummary);
        if (options.usageLog === true) {
          await recordUsage($, usageRecord({ project, model: baseModel(turn.model), record: turn.record,
            outcome: e.reason, durationMs: e.durationMs, usage: e.usage }));
        }
      }
      return result;
    } finally {
      if (turns.get(e.turnId) === turn) turns.delete(e.turnId);
    }
  });

  // Subagents carry no parent turn id and no prompt text, so a subagent turn is
  // bound at its first step to the main turn still running then (the one that
  // spawned it). Later steps keep that binding after the main turn ends.
  function subagentEffort(e) {
    if (!subagents.has(e.turnId)) {
      const main = [...turns.values()].find(turn => turn.started && !turn.completing);
      const inherit = mode === 'enforce' && main?.applied && main.record?.applied &&
        e.effort === main.requested && (e.model ?? null) === main.model;
      // A held-out main turn keeps its subagents unchanged too: they are its control arm.
      subagents.set(e.turnId, { effort: inherit ? main.applied : undefined, requested: main?.requested, model: main?.model,
        stepModel: e.model ?? null, record: main?.record && { ...main.record, applied: inherit ? main.applied : undefined,
          yielded: false, latencyMs: null } });
    }
    const bound = subagents.get(e.turnId);
    if (bound.record) bound.record.forwarded = safeEffort(e.effort);
    // The user changed effort or model: their choice wins for this subagent.
    if (bound.effort && (e.effort !== bound.requested || (e.model ?? null) !== bound.model)) {
      bound.effort = undefined;
      bound.record.yielded = true;
    }
    return bound.effort;
  }

  on('turn.step', async function* ($, e, next) {
    if (e.agentId !== undefined) {
      const effort = routing() ? subagentEffort(e) : undefined;
      return yield* next(effort ? { ...e, effort } : e);
    }
    if (!routing()) return yield* next(e);
    const turn = turns.get(e.turnId);
    if (!turn || turn.completing || turn.silent) return yield* next(e);
    if (turn.started) {
      if (turn.model !== (e.model ?? null)) invalidateTurn(turn);
      if (turn.record) turn.record.forwarded = safeEffort(e.effort);
      if (turn.applied && e.effort !== turn.requested) {
        // The user changed effort mid-turn; their choice wins for the rest of it.
        turn.applied = undefined;
        if (turn.record) turn.record.yielded = true;
      }
      return yield* next(turn.applied ? { ...e, effort: turn.applied } : e);
    }
    turn.started = true;
    turn.model = e.model ?? null;
    const effort = safeEffort(e.effort);
    const record = { provider, mode, original: effort,
      recommendation: 'keep', forwarded: effort, reasonCode: turn.valid ? 'correlation' : turn.reason, latencyMs: null };
    if (turn.valid && e.index === 0 && effort !== 'max' && effort !== 'unsupported') {
      const taskContext = sendContext ? contextText(previous) : null;
      const timer = new AbortController();
      const began = await $.clock.now();
      if (!isActiveTurn(e.turnId, turn)) return yield* next(e);
      const cancelled = new Promise(resolve => { turn.cancel = () => resolve({ reason: 'cancelled' }); });
      let outcome;
      try {
        outcome = await Promise.race([
          Promise.resolve().then(() => {
            if (!isActiveTurn(e.turnId, turn)) return null;
            const state = { userPrompt: turn.text, currentEffort: e.effort, taskContext: null };
            if (provider === 'jev') {
              const routingInput = {
                host: 'claude-code', prompt: turn.text, cloudConsent: options.cloudConsent === true,
                target: { model: baseModel(e.model ?? null), source: e.model ? 'host' : 'unknown', supportedEfforts: null },
                effort: { value: e.effort, source: 'host' },
                event: { sessionId: null, turnId: e.turnId, correlated: true },
                context: taskContext ? { source: previous.answer?.trim() ? 'model-summary' : 'user-provided', text: taskContext, missingRequired: null }
                  : { source: 'prompt-only', missingRequired: null },
              };
              return classifyJev($, routingInput, options, flight, () => isActiveTurn(e.turnId, turn));
            }
            return classify(state);
          }).then(value => ({ value }), () => ({ reason: 'provider-error' })),
          $.clock.sleep(CLASSIFY_WAIT_MS, { signal: timer.signal }).then(() => ({ reason: 'timeout' })),
          cancelled,
        ]);
      } finally {
        timer.abort();
        turn.cancel = undefined;
        turn.text = '';
      }
      if (!isActiveTurn(e.turnId, turn)) return yield* next(e);
      Object.assign(record, classificationResult(provider, outcome));
      record.latencyMs = Math.max(0, (await $.clock.now()) - began);
      // These reasons mean no request left the machine.
      if (['no-consent', 'missing-key', 'busy', 'invalid-input'].includes(record.reasonCode)) record.latencyMs = null;
      else if (taskContext) record.contextSent = true;
      if (!turn.valid) return yield* next(e);
    } else if (e.effort === 'max') record.reasonCode = 'max';
    else if (effort === 'unsupported') record.reasonCode = 'unsupported';
    if (!routing() || turns.get(e.turnId) !== turn) return yield* next(e);
    turn.record = record;
    if (mode === 'enforce' && applicable(record)) {
      if (holdoutRate > 0 && random() < holdoutRate) {
        record.holdout = true;
        return yield* next(e);
      }
      record.applied = record.recommendation;
      turn.applied = record.recommendation;
      turn.requested = e.effort;
      return yield* next({ ...e, effort: turn.applied });
    }
    // Shadow always delegates the exact original object, including all fields.
    return yield* next(e);
  });
}

function classificationResult(provider, outcome) {
  const decision = provider === 'jev' ? outcome.value?.decision : parseDecision(outcome.value);
  let reasonCode = outcome.reason;
  if (reasonCode == null && provider === 'jev') reasonCode = outcome.value?.reason;
  if (reasonCode == null) {
    if (!decision) reasonCode = 'invalid-response';
    else if (provider === 'jev') reasonCode = 'unevaluated';
    else reasonCode = decision.contextSufficient ? 'shadow' : 'context';
  }
  const probability = provider === 'jev' ? decision?.selectedProbability : undefined;
  // Recorded only, not a gate: no calibrated threshold exists yet for these scores.
  const scores = provider === 'jev' && decision ? { contextScore: decision.contextScore, riskScore: decision.riskScore } : {};
  return { recommendation: decision?.choice ?? 'keep', reasonCode, ...(probability !== undefined ? { probability } : {}), ...scores };
}

// Only a validated, different effort is applied; keep, skips, max,
// unsupported efforts and low-probability Jev candidates leave the request unchanged.
function applicable(record) {
  return ['unevaluated', 'shadow'].includes(record.reasonCode) && record.recommendation !== 'keep' &&
    !belowApplyProbability(record.probability) &&
    EFFORTS.includes(record.recommendation) && record.recommendation !== 'max' &&
    EFFORTS.includes(record.original) && record.original !== 'max' && record.recommendation !== record.original;
}

// Previous prompt head and answer tail: a follow-up usually answers the
// answer's closing question or proposal.
export function contextText(previous) {
  const prompt = typeof previous?.prompt === 'string' ? previous.prompt.trim() : '';
  const answer = typeof previous?.answer === 'string' ? previous.answer.trim() : '';
  if (!prompt && !answer) return null;
  const head = prompt ? `Previous user request:\n${prompt.slice(0, CONTEXT_PROMPT_CHARS)}` : '';
  const label = 'Previous assistant answer (end):\n';
  const room = CONTEXT_TOTAL_CHARS - head.length - (head ? 2 : 0) - label.length;
  const tail = answer && room > 0 ? `${label}${answer.slice(-room)}` : '';
  return [head, tail].filter(Boolean).join('\n\n') || null;
}

function holdoutShare(value) {
  const share = Number(value);
  return Number.isFinite(share) && share > 0 && share <= 0.5 ? share : 0;
}

// Context variants such as claude-opus-5-5[1m] share the base model's effort
// behavior; the bracket suffix would otherwise fail the identifier check.
function baseModel(value) {
  return typeof value === 'string' ? value.replace(/\[[^\]]*\]$/, '') : value;
}

function safeEffort(value) {
  return EFFORTS.includes(value) ? value : 'unsupported';
}

function invalidateTurn(turn) {
  turn.valid = false;
  turn.applied = undefined;
  turn.record = undefined;
  turn.text = '';
  turn.cancel?.();
}

// shadow or enforce only when explicitly chosen; with Jev both send every
// session's prompts (after cloud consent), so the default stays off.
function startMode(options) {
  return ['shadow', 'enforce'].includes(options.defaultMode) ? options.defaultMode : 'off';
}

const REPORT_GROUPS = ['day', 'week', 'month', 'project', 'model', 'mode', 'kind', 'pair', 'all'];
const REPORT_HTML = '~/.claude/jet-router/usage-report.html';
const REPORT_USAGE = `절감 리포트: /jet-router report [${REPORT_GROUPS.join('|')}] [html]`;

// Runs the report script of the loaded plugin version, so the path always
// follows updates. Only fixed tokens reach the argv; nothing is interpolated.
async function runReport($, tokens) {
  const html = tokens.includes('html');
  const groups = tokens.filter(token => token !== 'html');
  if (groups.length > 1 || (groups.length && !REPORT_GROUPS.includes(groups[0]))) return REPORT_USAGE;
  const argv = ['node', `${$.plugin.root}/scripts/usage.mjs`, 'report', ...(html ? ['--html', REPORT_HTML] : ['--by', groups[0] ?? 'day'])];
  try {
    const result = await $.process.run(argv, { cwd: $.plugin.root, timeoutMs: 10000, env: { ...PROCESS_ENV } });
    if (result.exitCode !== 0) return `리포트 생성 실패\n${REPORT_USAGE}`;
    return String(result.stdout).trim() || '기록이 없습니다.';
  } catch { return `리포트 생성 실패\n${REPORT_USAGE}`; }
}

// Local token log for savings reports; a failure never affects the session.
async function recordUsage($, record) {
  try {
    await $.process.run(['node', `${$.plugin.root}/scripts/usage.mjs`, 'record'], {
      cwd: $.plugin.root, stdin: JSON.stringify(record), timeoutMs: 3000, env: { ...PROCESS_ENV },
    });
  } catch { /* Logging is optional. */ }
}

function publish($, text) {
  // Provider strings, prompts, errors, IDs and API keys never enter the UI.
  try { $.ui.log(text); } catch { /* Display is optional. */ }
}

async function classifyJev($, routingInput, options, flight, active) {
  if (options.cloudConsent !== true) return { reason: 'no-consent' };
  if (!validJevKey(options.jevApiKey)) return { reason: 'missing-key' };
  const prepared = prepareRoutingRequest(routingInput);
  if (prepared.status !== 'ready') return { reason: 'invalid-input' };
  if (!active()) return { reason: 'cancelled' };
  if (flight.busy) return { reason: 'busy' };
  flight.busy = true;
  try {
    const result = await $.process.run(['node', `${$.plugin.root}/scripts/jev-request.mjs`], {
      cwd: $.plugin.root,
      stdin: JSON.stringify({ apiKey: options.jevApiKey, routingInput }),
      timeoutMs: PROCESS_TIMEOUT_MS,
      env: { ...PROCESS_ENV },
    });
    return parseHelperResult(result, prepared.choices);
  } catch { return { reason: 'provider-error' }; }
  finally { flight.busy = false; }
}

