    "provider": {
      "type": "string",
      "title": "Classifier",
      "description": "fake is offline. Jev requires explicit cloud consent and an API key.",
      "options": [
        "fake",
        "jev"
      ],
      "default": "fake"
    },
    "defaultMode": {
      "type": "string",
      "title": "Mode at session start",
      "description": "off (default), shadow or enforce. With Jev, shadow and enforce send each session's prompts after cloud consent; enforce also changes effort for the turn and its subagents.",
      "options": [
        "off",
        "shadow",
        "enforce"
      ],
      "default": "off"
    },
    "usageLog": {
      "type": "boolean",
      "title": "Record local token usage",
      "description": "Append one line per routed turn (effort decision and token counts, never prompt text) to ~/.claude/jet-router/usage for savings reports.",
      "default": true
    },
    "holdoutRate": {
      "type": "string",
      "title": "Enforce control share",
